mapper.select:
select id,name,type, mark_man, mark_man_id,dept_id,
is_deleted,create_man ,create_man_id,create_date ,modify_man ,modify_man_id,modify_date
from label_category a

    and a.id = #{id}
    and a.full_cn_name like concat('%',#{fullCnName},'%')
    and a.eg_name like concat('%',#{egName},'%')

        and a.status in

            #{item}



        and a.create_man_id in

            #{item}



        and a.id not in

            #{item}



        and a.id  in

            #{item}



        and a.track_map_id  in

            #{item}



        and a.create_date >= #{createDateStart} and a.create_date <= #{createDateEnd}


        and a.modify_date >= #{modifyDateStart} and a.modify_date <= #{modifyDateEnd}

    and a.is_deleted=false

select id,name,type, mark_man, mark_man_id,dept_id,
is_deleted,create_man ,create_man_id,create_date ,modify_man ,modify_man_id,modify_date
from label_category

     id = #{id}
    and flow_id = #{flowId}
    and is_deleted=false
